/* Original creator's existing child pipe; no new listener or tunnel broker. */
import {spawn} from 'node:child_process';
import {randomUUID} from 'node:crypto';
import path from 'node:path';
import {mkdir, lstat} from 'node:fs/promises';

const MAX_BYTES = 16384;
const RETAINED_OPERATIONS = new Set(['owner-drain','touch-release','touch-inspect','touch-settle']);
export class OriginalUserspaceKeeper {
  constructor(child, target) {
    this.child=child;this.target=target;this.instance=null;this.pending=new Map();
    this.failed=false;this.session=null;this.closing=false;this.touchDrainConfirmed=false;this.closeAttempt=null;
    this.ready=new Promise((resolve,reject)=>{this.resolveReady=resolve;this.rejectReady=reject;});
    this.partial='';
    const line=raw=>{
      try {
        if(Buffer.byteLength(raw)>MAX_BYTES)throw new Error();
        const value=JSON.parse(raw);
        if(value?.schemaVersion!==2)throw new Error();
        if(value.event==='owner-ready' && this.instance===null && /^[0-9a-f]{32}$/.test(value.ownerInstance)) {
          this.instance=value.ownerInstance;this.resolveReady(this);return;
        }
        if(value.ownerInstance!==this.instance || !/^[0-9a-f]{32}$/.test(value.requestId))throw new Error();
        const pending=this.pending.get(value.requestId);
        if(!pending || !['complete','failed'].includes(value.status))throw new Error();
        this.pending.delete(value.requestId);clearTimeout(pending.timer);
        if(pending.expired)return; // Keep original effect ownership; never replay.
        if(value.status==='complete')pending.resolve(value.result);
        else pending.reject(new Error('Original keeper operation failed'));
      } catch (_) {this.poison();}
    };
    child.stdout.on('data',chunk=>{
      if(this.failed)return;
      for(const byte of chunk) {
        if(byte===10) {const raw=this.partial;this.partial='';line(raw);}
        else if(byte>127 || this.partial.length>=MAX_BYTES) {this.poison();return;}
        else this.partial+=String.fromCharCode(byte);
      }
    });
    child.once('error',()=>this.poison());child.once('exit',()=>this.poison());
    // Existing keeper errors are deliberately not forwarded with target data.
    child.stderr.resume();
  }
  poison() {
    this.failed=true;this.rejectReady(new Error('Original keeper unavailable'));
    for(const pending of this.pending.values()) {
      clearTimeout(pending.timer);pending.expired=true;
      pending.reject(new Error('Original keeper unavailable'));
    }
    // Leave originals retained until child exit/explicit creator cleanup.
  }
  async request(request) {
    await this.ready;
    const retained=RETAINED_OPERATIONS.has(request?.operation);
    // Reserve four of the EXISTING32 pending slots for original cleanup. A
    // timed-out control remains owned; never replay/coalesce it as fresh data.
    if(this.failed || this.child.exitCode!==null || this.child.signalCode!==null ||
       this.pending.size>=(retained?32:28) || (this.closing && !retained) ||
       (retained && [...this.pending.values()].some(row=>row.operation===request.operation)) ||
       request?.schemaVersion!==2 || request.ownerInstance!==this.instance ||
       !/^[0-9a-f]{32}$/.test(request.requestId) || typeof request.operation!=='string' ||
       !request.args || typeof request.args!=='object' || Array.isArray(request.args) ||
       !(request.sessionId===null || typeof request.sessionId==='string'))throw new Error('Original keeper unavailable');
    if(this.pending.has(request.requestId))throw new Error('Original keeper request remains owned');
    if(request.operation==='claim') {
      if(this.session!==null || request.sessionId!==request.args.sessionId)throw new Error('Original keeper session changed');
      this.session=request.sessionId;
    } else if(request.operation==='owner-drain') {
      if(request.sessionId!==null)throw new Error('Original keeper owner scope changed');
    } else if(request.operation!=='inspect' && this.session!==request.sessionId)throw new Error('Original keeper session changed');
    const raw=JSON.stringify(request)+'\n';
    if(Buffer.byteLength(raw)>MAX_BYTES)throw new Error('Original keeper request too large');
    return await new Promise((resolve,reject)=>{
      const pending={resolve,reject,expired:false,timer:null,operation:request.operation};this.pending.set(request.requestId,pending);
      // Existing WDA bootstrap max35s; reads5s; touch intent remains <=12s.
      const budget=request.operation==='wda-start'?35000:
        ['touch-begin','touch-release','touch-settle','wda-stop'].includes(request.operation)?15000:5000;
      pending.timer=setTimeout(()=>{
        pending.expired=true;reject(new Error('Original keeper return is unresolved'));
        // Do not cancel a child/SDK call or treat timeout as Up/release.
      },budget);
      this.child.stdin.write(raw,error=>{if(error)this.poison();});
    });
  }
  async inspect() {
    return await this.request({schemaVersion:2,ownerInstance:this.instance,requestId:randomUUID().replaceAll('-',''),
      operation:'inspect',sessionId:null,args:{}});
  }
  async close() {
    this.closing=true; // Synchronous: no future claim/Down/forward operation.
    if(this.closeAttempt)return await this.closeAttempt;
    const attempt=this.closeOriginal();this.closeAttempt=attempt;
    try{return await attempt;}
    finally {if(this.closeAttempt===attempt)this.closeAttempt=null;}
  }
  async closeOriginal() {
    const deadline=performance.now()+12000;
    const dead=()=>this.child.exitCode!==null || this.child.signalCode!==null;
    const originalExit=()=>{
      if(!this.touchDrainConfirmed || this.child.exitCode!==0 || this.child.signalCode!==null)
        throw new Error('Original keeper responsibility remains unqualified');
    };
    if(dead()){originalExit();return;}
    if(this.failed || this.instance===null)throw new Error('Original keeper remains retained without a drain return');
    // Existing pipe only; the actual child closes input admission, awaits its
    // original born workers and already-issued operations, then answers.
    const value=await this.request({schemaVersion:2,ownerInstance:this.instance,
      requestId:randomUUID().replaceAll('-',''),sessionId:null,operation:'owner-drain',args:{}});
    if(!value || typeof value!=='object' || Array.isArray(value) ||
       Object.keys(value).sort().join(',')!=='inputAdmissionClosed,nativeTouchSupport,originalKeeperDrainVersion,originalOperationsSettled,originalTouchWorkersSettled,ownerInstance,resourceRetirementEstablished' ||
       value.originalKeeperDrainVersion!==1 || value.ownerInstance!==this.instance ||
       value.inputAdmissionClosed!==true || value.originalTouchWorkersSettled!==true ||
       value.originalOperationsSettled!==true || value.nativeTouchSupport!==false ||
       value.resourceRetirementEstablished!==false)
      throw new Error('Original keeper drain return is unavailable');
    this.touchDrainConfirmed=true;
    if(dead()){originalExit();return;}
    const exited=new Promise(resolve=>this.child.once('exit',resolve));
    // SIGTERM is allowed ONLY after the original host drain return. Never
    // force-kill/cancel an unresolved Down/task or discard its actual child.
    this.child.kill('SIGTERM');let timer;
    const graceful=await Promise.race([exited.then(()=>true),new Promise(resolve=>{
      timer=setTimeout(()=>resolve(false),Math.max(0,deadline-performance.now()));
    })]);clearTimeout(timer);
    if(!graceful && !dead())throw new Error('Original keeper remains retained during final exit');
    originalExit();
  }
}

export async function startOriginalUserspaceKeeper(device, onOriginalBirth) {
  const helper=process.env.OVERTE_PYMOBILEDEVICE3_XCTEST_HELPER;
  const packages=process.env.OVERTE_PYMOBILEDEVICE3_SITE_PACKAGES;
  const home=process.env.XDG_DATA_HOME;
  if([helper,packages,home].some(value=>typeof value!=='string'||!path.isAbsolute(value)||/[\0\r\n]/.test(value)))
    throw new Error('Pinned original creator resources unavailable');
  const stateRoot=path.join(home,'original-userspace-'+randomUUID().replaceAll('-',''));
  await mkdir(stateRoot,{mode:0o700});const state=await lstat(stateRoot);
  if(!state.isDirectory()||state.isSymbolicLink()||(state.mode&0o077)!==0||state.uid!==process.geteuid())
    throw new Error('Private original keeper state unavailable');
  const child=spawn('/usr/bin/python3.14',['-S','-P','-B',helper],{
    cwd:'/',stdio:['pipe','pipe','pipe'],windowsHide:true,
    env:{HOME:home,LANG:'C.UTF-8',LC_ALL:'C.UTF-8',PATH:'/usr/bin',PYTHONNOUSERSITE:'1',PYTHONDONTWRITEBYTECODE:'1',
      PYTHONPATH:packages}});
  const owner=new OriginalUserspaceKeeper(child,device.Properties.SerialNumber);
  // Original creator synchronously retains the ACTUAL child before bootstrap
  // can await/fail. This callback retains custody; it supplies no auth fact.
  onOriginalBirth(owner);
  child.stdin.write(JSON.stringify({schemaVersion:2,creatorMode:'original-userspace-owner',
    udid:owner.target,stateRoot})+'\n');
  let timer;
  try {
    await Promise.race([owner.ready,new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error('Original creator start timeout')),35000);})]);
    await owner.inspect();return owner;
  } catch(error) {await owner.close();throw error;}
  finally {clearTimeout(timer);}
}
